-- 마스터 FK 연결 (코드 기준)
update legacy_settlements l set retailer_id = r.id
  from retailers r where r.code = l.retailer_code and l.retailer_id is null;
update legacy_settlements l set workshop_id = w.id
  from workshops w where w.code = l.workshop_code and l.workshop_id is null;

-- 확인용
select period_key, period_label,
       sum(case when item='SP' then amount end)        as 판매대금_AR,
       sum(case when item='SAVEBACK' then amount end)  as 사용반환금_AP,
       sum(case when item='SUPPORT' then amount end)   as JLRK기여금_AP,
       sum(case when item='INCENTIVE' then amount end) as 인센티브_AP,
       count(*) as rows
from legacy_settlements
group by period_key, period_label
order by min(coalesce(data_month, settle_month));

select count(*) filter (where retailer_id is null) as retailer_미연결,
       count(*) filter (where workshop_id is null) as workshop_미연결,
       count(*) as total
from legacy_settlements;
